"""
Business Ops Intent v0.

Deterministic intent classification for the Business Ops Spine.
Unifies keyword-based intent detection across Gmail, Calendar, Payments, and Files.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Optional


@dataclass(frozen=True)
class IntentFrame:
    intent_name: str
    request_category: str
    domain: str
    confidence: float
    trigger: Optional[str] = None


def classify_business_ops_intent(query: str) -> IntentFrame:
    """
    Deterministic intent classification based on keywords and phrases.
    """
    q = (query or "").lower().strip()
    # Normalize curly apostrophes and strip common sentence-ending/prefix-separating punctuation
    q = q.replace("’", "'").replace("‘", "'")
    q = q.strip("?.!,").strip()

    # 1. User denial phrases (Highest priority)
    if any(phrase in q for phrase in ("no gmail", "no email", "no tools", "without gmail", "without email")):
        return IntentFrame("deny", "stop", "none", 1.0)

    # 2. Background / Automated (Internal use)
    if q == "monitored_email_conversation":
        return IntentFrame("monitored_email_conversation", "automated", "email", 1.0)

    # 3. Status / Orientation (High priority for explicit orientation)
    # Explicit OpenClaw orientation/status questions (High confidence)
    explicit_status_phrases = (
        "where are we", "openclaw status", "system status", "orientation",
        "lay of the land", "where do things stand", "what's the move",
        "catch me up", "orient me"
    )
    if any(phrase in q for phrase in explicit_status_phrases):
        # Prevent false positives with specific context blockers
        if not any(blocker in q for blocker in ("weather", "invoice", "email", "dinner", "lunch")):
            # Overriding 'thread' or 'subject' if 'catch me up' or 'orientation' is present
            return IntentFrame("ops_status", "read_only", "logging", 1.0, "explicit_status")

    # 4. Email / Gmail
    email_terms = (
        "email", "gmail", "inbox", "message", "unread", "sender",
        "subject", "from", "reply", "draft", "thread", "attachment"
    )
    for term in email_terms:
        if term in q:
            return IntentFrame("email_search", "read_only", "email", 0.9, term)

    # 5. Calendar
    calendar_terms = (
        "calendar", "schedule", "appointment", "meeting", "event",
        "tomorrow morning", "tomorrow afternoon", "this week", "next week",
        "what's on", "what do i have", "what's tomorrow", "what's today"
    )
    for term in calendar_terms:
        if term in q:
            return IntentFrame("calendar_read", "read_only", "calendar", 0.9, term)

    # 6. Payment / Billing
    payment_terms = (
        "invoice", "payment", "paid", "unpaid", "receivable",
        "owes", "owed", "client follow-up", "balance", "overdue",
        "deposit", "cleared", "transfer", "funds"
    )
    for term in payment_terms:
        if term in q:
            return IntentFrame("payment_verify", "read_only", "payment", 0.9, term)

"""
cassandra_identity.py

Contact identity resolution for Cassandra.

Loads contact_nicknames.json, normalizes entries, and provides lookup/verification
functions used by cassandra_brain.py, cassandra_listener.py, and tests.

Public API
----------
find_contact_by_nickname(nickname)          — lookup by nickname
is_designated_contact_sender(name, chat_id) — boolean contact check
is_pinned_on_channel(nickname, channel)     — channel pin check
verify_sender_on_channel(name, id, channel) — full channel verification
"""

from __future__ import annotations

import difflib
import json
import re
from pathlib import Path

_NICKNAMES_PATH = Path("/home/openclaw/contact_nicknames.json")


def _load_nicknames() -> dict:
    """Load contact_nicknames.json. Returns empty dict on any error."""
    try:
        data = json.loads(_NICKNAMES_PATH.read_text(encoding="utf-8"))
        return {k.lower(): v for k, v in data.items() if not k.startswith("_")}
    except Exception:
        return {}


def _normalize_contact_entry(nickname: str, raw: object) -> dict:
    names: set[str] = {nickname.lower()}
    chat_ids: set[str] = set()
    if isinstance(raw, str):
        names.add(raw.lower())
        display_name = raw
    elif isinstance(raw, dict):
        display_name = (
            raw.get("name")
            or raw.get("display_name")
            or raw.get("real_name")
            or nickname
        )
        for key in ("name", "display_name", "real_name", "telegram_name", "sender_name"):
            value = raw.get(key)
            if isinstance(value, str) and value.strip():
                names.add(value.strip().lower())
        for key in ("aliases", "sender_names"):
            values = raw.get(key, [])
            if isinstance(values, list):
                for value in values:
                    if isinstance(value, str) and value.strip():
                        names.add(value.strip().lower())
        for key in ("telegram_chat_id", "chat_id"):
            value = raw.get(key)
            if value not in (None, ""):
                chat_ids.add(str(value))
        values = raw.get("telegram_chat_ids", [])
        if isinstance(values, list):
            for value in values:
                if value not in (None, ""):
                    chat_ids.add(str(value))
    else:
        display_name = nickname
    tier = raw.get("tier", "inner_circle") if isinstance(raw, dict) else "inner_circle"
    response_sla = raw.get("response_sla") if isinstance(raw, dict) else None
    pinned_email = None
    pinned_phone = None
    pinned_whatsapp = None
    if isinstance(raw, dict):
        v = raw.get("pinned_email")
        if isinstance(v, str):
            normalized = v.strip().lower()
            pinned_email = normalized or None
        v = raw.get("pinned_phone")

#!/usr/bin/env python3
"""Resilient 8:00 AM EST CEO briefing worker for Deep-Flight autopilot."""

from __future__ import annotations

import time
from datetime import datetime
from pathlib import Path

try:
    from zoneinfo import ZoneInfo
except Exception:  # pragma: no cover
    ZoneInfo = None  # type: ignore

import chief_ceo_briefing as brief

SENTINEL_DIR = Path("/mnt/c/OpenClaw/logs")
WORKER_LOG = SENTINEL_DIR / "ceo_briefing_worker.log"
MAX_RETRIES = 5
RETRY_SLEEP = 600  # 10 min


def _log(msg: str) -> None:
    SENTINEL_DIR.mkdir(parents=True, exist_ok=True)
    with open(WORKER_LOG, "a", encoding="utf-8") as f:
        f.write(f"[{datetime.now().isoformat()}] {msg}\n")


def _sentinel(today_key: str) -> Path:
    return SENTINEL_DIR / f"ceo_briefing_sent_{today_key}.txt"


def _now_est() -> datetime:
    if ZoneInfo:
        return datetime.now(ZoneInfo("America/New_York"))
    return datetime.now()


def _try_send_with_retries(today_key: str) -> bool:
    for attempt in range(1, MAX_RETRIES + 1):
        ok, detail = brief.send_summary()
        if ok:
            _sentinel(today_key).write_text(f"sent at {_now_est().isoformat()} via {detail}\n", encoding="utf-8")
            _log(f"sent on attempt={attempt} via {detail}")
            return True
        _log(f"attempt={attempt} failed: {detail}")
        if attempt < MAX_RETRIES:
            time.sleep(RETRY_SLEEP)
    return False


def main() -> None:
    brief._load_env()
    _log("worker started")

    while True:
        now = _now_est()
        today_key = now.date().isoformat()
        sent_file = _sentinel(today_key)

        if now.hour == 8 and now.minute == 0 and not sent_file.exists():
            _log("8:00 window reached; sending briefing")
            _try_send_with_retries(today_key)

        time.sleep(30)


if __name__ == "__main__":
    main()
